INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", "お！\nあそこに困ってそうな人発見！", 1.4, "春咲 ひより", 2, 0, 1, 1, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 1, 0, 1001);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "みんなみたいに\nわたしも強くならなきゃ", "大切な人を\n守れるようになりたい…って", 1.4, "草野 優衣", 2, 0, 1, 1, "わ、わたし、\nなに言ってるんだろ\nあはは…", 1, 0, 1002);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "フェンシングを始めてみては？", "キミに必要な集中力と感性が", 1.4, "士条 怜", 2, 0, 1, 1, "少しは磨かれると思いますよ。", 1, 0, 1003);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "ねぇ、にいちゃん！", "今日はなにして遊ぶ？", 1.5, "穂高 みそぎ", 2, 0, 1, 1, "みそぎはねぇ、\nかくれんぼやりたい！", 1, 0, 1004);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "風宮あかりです", "ねぇ…", 1.4, "風宮 あかり", 2, 0, 1, 1, "私といっしょに…\nいかない？", 1, 0, 1006);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "出雲宮子なのー", "プリンたべたいのー", 1.5, "出雲 宮子", 2, 0, 1, 1, "食べ物の恨みは怖いのー", 1, 0, 1007);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "ボクは虹村雪。", "キミもボクの美貌に\n吸い寄せられたんだね。", 1.4, "虹村 雪", 2, 0, 1, 1, "いいよ。\n見られることは運命さ…", 1, 0, 1008);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "フッ…聞いて後悔するがいい！", "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 1.4, "柊杏奈", 2, 0, 1, 1, "人呼んで「疾風の冥姫」!!", 1, 0, 1009);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "マホマホ王国のプリンセス、\nまほ姫どす", "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 1.5, "姫宮 真歩", 2, 0, 1, 1, "ほんまおおきにやわ～♪", 1, 0, 1010);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "衣之咲璃乃です！", "生き別れたお兄ちゃんを探して\n三千世界！", 1.4, "衣之咲 璃乃", 2, 0, 1, 1, "ここで会ったが\n100年目～！", 1, 0, 1011);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "私はハツネ、\n結構強いんだよ。\nきらーん☆", "ち、超能力って…\n何のことかな～？", 1.4, "柏崎 初音", 2, 0, 1, 1, "…って、お願い！\n誰にも言わないでおいて～！", 1, 0, 1012);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "ちょす！\n美波鈴奈だよ～♪", "一応カリスマ読モJKやってまっす！", 1.4, "美波 鈴奈", 2, 0, 1, 1, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 1, 0, 1016);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "はいたーい。\n喜屋武香織さー。", "東京は遊園地みたいなところさー", 1.4, "喜屋武 香織", 2, 0, 1, 1, "でも、沖縄もとってもいいとこさー", 1, 0, 1017);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "支倉伊緒です。", "先生って呼ばれるのは\nくすぐったいから", 1.4, "支倉 伊緒", 2, 0, 1, 1, "イオちゃんって呼んでね。", 1, 0, 1018);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", "あ！/\お兄ちゃ～ん\nまってよ～", 1.5, "茜 ミミ", 2, 0, 1, 1, "ミミをおいてかないでぇ～", 1, 0, 1020);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "あ…あの…えっと…\n栗…林…くるみ…です……", "あの……\nふぇ……", 1.5, "栗林 くるみ", 2, 0, 1, 1, "ふぇぇぇぇぇん……", 1, 0, 1021);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "風宮よりです。\nあああああ！", "こんな私に貴重な時間を\n割いていただき、", 1.4, "風宮 より", 2, 0, 1, 1, "なんてありがとうございます！", 1, 0, 1022);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", "おにいちゃんどこいくの？\nえ？", 1.5, "北条 綾音", 2, 0, 1, 1, "私こっち行きたいー\nね、早く早くー", 1, 0, 1023);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "わっ…わっ…私、\n天野すずめといいます！", "ふ、不束者ですが\nどうぞ末永く…って、", 1.4, "天野 すずめ", 2, 0, 1, 1, "これて何か違う…\nあああすみません！", 1, 0, 1025);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "……クスクス…私は\n…倉石恵理子……", "あなたは…運命の……\n伴侶……", 1.4, "倉石 恵理子", 2, 0, 1, 1, "離しませんわ………\n絶対に…!!", 1, 0, 1027);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 1.4, "佐々木 咲恋", 2, 0, 1, 1, "…そうでしょ？？", 1, 0, 1028);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "桜井望だよ！\nよろしくねっ", "ぇっと…\nキミ、私のこと知らないの?!", 1.4, "桜井 望", 2, 0, 1, 1, "あはは、\n私もまだまだだなぁ～", 1, 0, 1029);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "デケデケデンっ！", "初めまして、\n私はニノン・ジュベール申すデス！", 1.4, "ニノン・ジュベール", 2, 0, 1, 1, "ショーグン、\nワタシと一緒に天下統一デース！", 1, 0, 1030);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "上喜しのぶです。\n手元のドクロが父です。", "でもって私の隣にいるのが……\nえ、見えない？", 1.4, "上喜 しのぶ", 2, 0, 1, 1, "おかしいですね……", 1, 0, 1031);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "目指すはビッグな\nお笑い芸人だっぺ！", "けんども\nそれには足りないモンが…", 1.5, "野戸まひる", 2, 0, 1, 1, "そう、\nオラのボケに突っ込める相方が…！", 1, 0, 1033);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", "ちょっと緊張しちゃって…", 1.4, "綾瀬 ゆかり", 2, 0, 1, 1, "ちょ\nちょっと一杯飲んできます…！", 1, 0, 1034);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "氷川鏡華…です", "知らない人とは話しちゃいけないので", 1.5, "氷川 鏡華", 2, 0, 1, 1, "これ以上お話しすることは…\nないです！", 1, 0, 1036);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "柏崎…栞です。", "……あ、アラーム。", 1.4, "柏崎 栞", 2, 0, 1, 1, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 1, 0, 1038);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "ふ、双葉碧です。", "私、一人も友達がいなくて……", 1.4, "双葉 碧", 2, 0, 1, 1, "野に咲く花が、\n唯一の話相手です。", 1, 0, 1040);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "三角千歌です。", "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 1.4, "三角 千歌", 2, 0, 1, 1, "そう思っています。", 1, 0, 1042);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "安芸真琴だ。", "あぁ？\nお前のそいつの仲間か？", 1.4, "安芸 真琴", 2, 0, 1, 1, "う、疑ってすまなかったな…", 1, 0, 1043);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "わらわこそは夜を総べる者！", "生けとし生ける全ての者よ！", 1.4, "イリヤ・オーンスタイン", 2, 0, 1, 1, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 1, 0, 1044);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "そこで騎士は妖精を乱暴に……", "ぐふふふふ……はっ！", 1.4, "遠見 空花", 2, 0, 1, 1, "ｌク、クウカに何かご用ですか!?", 1, 0, 1045);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "宮坂たまきにゃ♪\n猫はいいにゃよ？", "自由気ままで♪\n寝て遊んで、食べてケンカして…", 1.4, "宮坂たまき", 2, 0, 1, 1, "う～ん…\n猫ってホントに最高にゃ～♪", 1, 0, 1046);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "大神美冬よ！", "それでは早速クエストに…", 1.4, "大神 美冬", 2, 0, 1, 1, "…と思ったら\nバイトの時間だ！\nまたあとでね！", 1, 0, 1048);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "星野静流だよ！", "クエストもバトルも\n掃除も洗濯も", 1.4, "星野静流", 2, 0, 1, 1, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 1, 0, 1049);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "アタシは玉泉美咲。", "見ての通りの\nセクシー美少女で", 1.5, "玉泉美咲", 2, 0, 1, 1, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 1, 0, 1050);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "？？？", "？？？？", 1.4, "リマ", 2, 0, 1, 1, "？？？？", 1, 0, 1052);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "モニカ・ヴァイスヴィントだ。", "菓子でつろうなどと\n稚拙な策を……", 1.5, "モニカ・ヴァイスヴィント", 2, 0, 1, 1, "そ、そこまでいうなら\nもらってやる", 1, 0, 1053);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "モニカ・ヴァイスヴィントだ。", "菓子でつろうなどと\n稚拙な策を……", 1.5, "ペコリーヌ", 2, 0, 1, 1, "そ、そこまでいうなら\nもらってやる", 1, 0, 1058);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "モニカ・ヴァイスヴィントだ。", "菓子でつろうなどと\n稚拙な策を……", 1.5, "コッコロ", 2, 0, 1, 1, "そ、そこまでいうなら\nもらってやる", 1, 0, 1059);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 0, 0, "モニカ・ヴァイスヴィントだ。", "菓子でつろうなどと\n稚拙な策を……", 1.5, "キャル", 2, 0, 1, 1, "そ、そこまでいうなら\nもらってやる", 1, 0, 1060);
